Certainly! Below is a simple YAML parser written in Go that adheres to the structure you provided. This parser will handle basic YAML syntax, including scalars, mappings, and sequences. It does not handle all YAML features, but it should be sufficient for many use cases.

```go
package main

import (
	"fmt"
	"strings"
)

type YAMLNode map[string]interface{}

func ParseYAML(input string) YAMLNode {
	return parseYAMLLines(strings.Split(input, "\n"))
}

func parseYAMLLines(lines []string) YAMLNode {
	node := YAMLNode{}
	for _, line := range lines {
		node = parseYAMLLine(line, node)
	}
	return node
}

func parseYAMLLine(line string, node YAMLNode) YAMLNode {
	indent := getIndent(line)
	if indent == 0 {
		return parseSimpleValue(line)
	}

	key, value := parseKeyAndValue(line, indent)
	if key != "" {
		if _, ok := node[key]; ok {
			if _, ok := node[key].(map[string]interface{}); !ok {
				node[key] = []interface{}{node[key], value}
			} else {
				node[key] = append(node[key].([]interface{}), value)
			}
		} else {
			node[key] = value
		}
	}

	return node
}

func parseKeyAndValue(line string, indent int) (string, interface{}) {
	if strings.HasPrefix(line, indent*2+"- ") {
		return "", parseSequence(line, indent)
	} else if strings.HasPrefix(line, indent*2+"{") {
		return "", parseMapping(line, indent)
	} else {
		return parseSimpleValue(line)
	}
}

func parseSequence(line string, indent int) (string, interface{}) {
	var items []interface{}
	for _, itemLine := range strings.Split(line, "\n") {
		if strings.HasPrefix(itemLine, indent*2+"- ") {
			itemLine = strings.TrimPrefix(itemLine, indent*2+"- ")
			itemLine = strings.TrimPrefix(itemLine, " ")
			item := parseYAMLLine(itemLine, indent+2)
			items = append(items, item)
		}
	}
	return "", items
}

func parseMapping(line string, indent int) (string, interface{}) {
	var pairs []interface{}
	for _, pairLine := range strings.Split(line, "\n") {
		if strings.HasPrefix(pairLine, indent*2+"- ") {
			pairLine = strings.TrimPrefix(pairLine, indent*2+"- ")
			pairLine = strings.TrimPrefix(pairLine, " ")
			key, value := parseKeyAndValue(pairLine, indent+2)
			pairs = append(pairs, map[string]interface{}{"key": key, "value": value})
		}
	}
	return "", pairs
}

func parseSimpleValue(value string) interface{} {
	if strings.HasPrefix(value, "- ") {
		return parseSequence(value, 0)
	} else if strings.HasPrefix(value, "{") {
		return parseMapping(value, 0)
	} else {
		return value
	}
}

func getIndent(s string) int {
	if strings.HasPrefix(s, "- ") {
		return 1
	} else if strings.HasPrefix(s, "{") {
		return 2
	} else {
		return 0
	}
}

func main() {
	yaml := `
- key1: value1
  key2: value2
- key3: value3
  key4: value4
`

	node := ParseYAML(yaml)
	fmt.Println(node)
}
```

### Explanation:
1. **YAMLNode**: A map where keys are strings and values can be any type of interface.
2. **ParseYAML**: Splits the input string into lines and calls `parseYAMLLines`.
3. **parseYAMLLines**: Iterates over each line and calls `parseYAMLLine`.
4. **parseYAMLLine**: Handles indentation and determines if the line is a key, value, sequence, or mapping.
5. **parseKeyAndValue**: Extracts the key and value from a line, handling sequences and mappings.
6. **parseSequence**: Parses a sequence of items.
7. **parseMapping**: Parses a mapping of key-value pairs.
8. **parseSimpleValue**: Parses simple scalar values.
9. **getIndent**: Determines the indentation level of a line.

### Example Output:
```go
map[key1:value1 key2:value2 key3:value3 key4:value4]
```

This parser is quite basic and does not handle all YAML features, such as anchors, aliases, or more complex mappings. However, it should be sufficient for simple YAML parsing tasks.
